SELECT *
FROM sieve
WHERE activation_rate BETWEEN 0.01 AND 0.50
  AND n_active >= 20
  AND (ABS(differential_return) > 0.003 OR ABS(pearson_corr) > 0.015)
ORDER BY cost_adjusted_ir DESC